ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def encrypt(message, key):
    out = []
    for ch in message.upper():
        if ch in ALPHABET:
            out.append(ALPHABET[(ALPHABET.index(ch) + key) % 26])
        else:
            out.append(ch)
    return "".join(out)


def decrypt(message, key):
    return encrypt(message, -key)


def crack(ciphertext, words):
    best_key, best_score = 0, -1
    for key in range(26):
        plain = decrypt(ciphertext, key)
        score = sum(1 for w in plain.split() if w in words)
        if score > best_score:
            best_key, best_score = key, score
    return best_key, decrypt(ciphertext, best_key)
